"""Seekable ground movements generated by the native airport simulator."""
from bisect import bisect_right
from copy import deepcopy
import gzip
import json


class GroundReplay:
    def __init__(self, path):
        with gzip.open(path, 'rt', encoding='utf-8') as stream:
            data = json.load(stream)
        self.flights = data['flights']
        self.events = data['events']
        self.milestones = data['milestones']
        self.times = {cs: [row[0] for row in f['samples']] for cs, f in self.flights.items()}

    def frame_at(self, now, fpl):
        aircraft = []
        for cs, flight in self.flights.items():
            if not flight['start_s'] <= now < flight['end_s']:
                continue
            points, times = flight['samples'], self.times[cs]
            index = max(0, bisect_right(times, now)-1)
            left = points[index]
            x, y, speed, altitude, vs = left[1:6]
            state, segment = left[6:8]
            if index+1 < len(points):
                right = points[index+1]
                # Never blend a hold, touchdown, or a route corner into another phase.
                if right[6:8] == left[6:8]:
                    fraction = (now-left[0])/(right[0]-left[0])
                    x, y, speed = [left[k]+fraction*(right[k]-left[k]) for k in (1, 2, 3)]
                    if altitude is not None and right[4] is not None:
                        altitude += fraction*(right[4]-altitude)
            aircraft.append(dict(callsign=cs, x=x, y=y, speed_kt=speed,
                altitude_ft=altitude, vertical_speed_fpm=vs, state=state,
                operation=flight['operation'], route=flight['route'], seg_idx=segment,
                manual_route=False, stand=flight['stand'], fpl=fpl.get(cs), metrics={}))
        events = [e for e in self.events if e['time_s'] <= now]
        milestones = {cs: {key: value for key, value in marks.items() if value <= now}
                      for cs, marks in self.milestones.items()}
        return dict(aircraft=aircraft, events=deepcopy(events[-200:]),
                    milestones={cs: marks for cs, marks in milestones.items() if marks})
